using Microsoft.EntityFrameworkCore;

public sealed class Order
{
    public Guid Id { get; set; }
    public decimal Total { get; set; }
}
public sealed record OrderPlaced(Guid OrderId, decimal Total);
public sealed class OutboxMessage
{
    public Guid Id { get; set; }
    public long Sequence { get; set; }
    public string Type { get; set; } = "";
    public string Payload { get; set; } = "";
    public DateTime? PublishedAt { get; set; }
}
public interface IMessageBus
{
    Task PublishAsync<T>(T message, CancellationToken ct);
    Task PublishAsync(Guid id, string type, string payload, CancellationToken ct);
}
public sealed class ShopDb(DbContextOptions<ShopDb> options) : DbContext(options)
{
    public DbSet<Order> Orders => Set<Order>();
    public DbSet<OutboxMessage> Outbox => Set<OutboxMessage>();
}
